# -*- coding: utf-8 -*-
"""constants.py — 포트/타이밍/색상/폰트/레이아웃/아이콘 등 앱 전역 상수.
lan_messenger.py에서 분리됨 (유지보수를 위해 여러 파일로 분할, v5.1)."""

DEFAULT_PORT = 50707
PRESENCE_INTERVAL = 3.0      # 감지 주기(초)
PEER_TIMEOUT = 12.0          # 이 시간 동안 응답이 없으면 목록에서 제거
MSG_RETRY_MAX = 3            # 전송 재시도 횟수
RETRY_WAIT = 1.2             # 재시도 대기(초)
MAX_LEN = 3000               # 메시지 최대 길이
GROUP_HISTORY_SNAPSHOT = 50  # 그룹 초대 시 함께 보내는 최근 대화 개수
GROUP_TIME_GAP = 300          # 같은 발신자의 연속 메시지 그룹핑 최대 시간 간격(초, 5분)
DEFAULT_MAX_FILE_SIZE = 1024 * 1024 * 1024   # 파일 전송 최대 크기 기본값(1024MB=1GB, v6.48부터
                                    # 20MB에서 상향 — 양쪽 다 이 값 이상이어야 그 크기 파일을 받을 수
                                    # 있는데(설정이 한쪽이라도 낮으면 상대가 조용히 거절), 기본값이
                                    # 낮으면 대용량 전송이 늘 막혀서 사용자가 매번 양쪽 설정을 먼저
                                    # 맞춰야 했다. 설정(⚙ 상대 연결 창)에서 1~1024MB 사이로 여전히
                                    # 사용자가 바꿀 수 있다(Engine.max_file_size, settings.json의
                                    # "max_file_size_mb").
MAX_FILE_SIZE_LIMIT_MB = 1024       # 사용자가 설정할 수 있는 상한(1GB)
FILE_CHUNK_SIZE = 32 * 1024        # 청크당 원본 32KB (base64 인코딩 후에도 UDP 세이프 마진 안)
IMAGE_EXTS = {".png", ".gif", ".bmp"}  # tkinter.PhotoImage가 외부 패키지 없이 직접 디코딩 가능한 형식
PIL_IMAGE_EXTS = {".jpg", ".jpeg"}     # Pillow가 있어야 미리보기 가능(없으면 파일카드로 자동 대체)
ALL_IMAGE_EXTS = IMAGE_EXTS | PIL_IMAGE_EXTS  # "사진"으로 분류할 전체 확장자(발신/수신 기록 태깅용)
# 대화창에서 받은 파일을 클릭해 열 때, 이 확장자면 실행 전 경고를 한 번 거친다
# (신뢰할 수 없는 상대가 보낸 실행 파일/스크립트를 무심코 클릭해 바로 실행되는 것 방지).
RISKY_FILE_EXTS = {".exe", ".bat", ".cmd", ".com", ".scr", ".pif", ".msi",
                    ".vbs", ".vbe", ".js", ".jse", ".wsf", ".wsh", ".ps1", ".ps1xml",
                    ".hta", ".jar", ".reg", ".lnk"}

